fn solve(input: Vec<i8>) -> Vec<&'static str> {
    // If the input is empty, there are no test cases.
    if input.is_empty() {
        return Vec::new();
    }
    // The first entry is the number of test cases t.
    let t = input[0] as usize;
    let mut result = Vec::with_capacity(t);

    for &x in input.iter().skip(1).take(t) {
        let n = x as i32;
        let winner = if n == 1 {
            // Rule: n = 1 ⇒ FastestFinger
            "FastestFinger"
        } else if n == 2 {
            // Rule: n = 2 ⇒ Ashishgup
            "Ashishgup"
        } else if n > 0 && (n & (n - 1)) == 0 {
            // Rule: power of two ⇒ FastestFinger
            "FastestFinger"
        } else if n % 4 != 2 {
            // Rule: n mod 4 ≠ 2 ⇒ Ashishgup
            "Ashishgup"
        } else {
            // Here n % 4 == 2 and n > 2
            let p = n / 2;
            // limited-prime test:
            //   p ≤ 1       ⇒ not prime
            //   p = 2       ⇒ prime
            //   even p > 2  ⇒ not prime
            //   odd p > 2   ⇒ prime
            let is_limited_prime = if p <= 1 {
                false
            } else if p == 2 {
                true
            } else {
                p % 2 != 0
            };
            if is_limited_prime {
                // Rule: n % 4 == 2 and p is limited-prime ⇒ FastestFinger
                "FastestFinger"
            } else {
                // Otherwise ⇒ Ashishgup
                "Ashishgup"
            }
        };
        result.push(winner);
    }

    result
}

